import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 62 After the fire","description":"学习 完成进行时与持续活动，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 62 After the fire","description":"学习 完成进行时与持续活动，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 完成进行时与持续活动，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 61 Trouble with the Hubble","link":"/life/english/new-concept/book-2/unit-03/lesson-061"},"next":{"text":"第二册：实践与进步 · Lesson 63 She was not amused","link":"/life/english/new-concept/book-2/unit-03/lesson-063"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 61 Trouble with the Hubble","link":"/life/english/new-concept/book-2/unit-03/lesson-061"},"next":{"text":"第二册：实践与进步 · Lesson 63 She was not amused","link":"/life/english/new-concept/book-2/unit-03/lesson-063"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-062.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-062.md"}'),i={name:"life/english/new-concept/book-2/unit-03/lesson-062.md"};function l(r,e,s,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-62-after-the-fire" tabindex="-1">第二册：实践与进步 · Lesson 62 After the fire <a class="header-anchor" href="#第二册-实践与进步-·-lesson-62-after-the-fire" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 62 After the fire&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>火灾后的土地恢复需要长期观察与补种，短期变化不能等于完全恢复；练习过去完成进行时。本课的语言观察是：had been planting 是过去参照点之前一直进行的活动；与 have been planting 的参照点在现在不同。需要明确过去的停顿或报告时刻。完成学习后，请描述一次持续劳动被天气打断的经历，补充一个较晚的观察结果。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>seed</td><td>/siːd/</td><td>n.</td><td>种子</td><td>plant a seed</td></tr><tr><td>soil</td><td>/sɔɪl/</td><td>n.</td><td>土壤</td><td>fertile soil</td></tr><tr><td>fire</td><td>/ˈfaɪə/</td><td>n.</td><td>火</td><td>put out a fire</td></tr><tr><td>grow</td><td>/ɡrəʊ/</td><td>v.</td><td>生长</td><td>grow steadily</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>put out a fire — 扑灭火</li><li>take root — 生根，也可比喻建立起来</li></ul><h2 id="语法讲解-完成进行时与持续活动" tabindex="-1">语法讲解：完成进行时与持续活动 <a class="header-anchor" href="#语法讲解-完成进行时与持续活动" aria-label="Permalink to &quot;语法讲解：完成进行时与持续活动&quot;">​</a></h2><p>现在完成进行时由 have/has been 加 -ing 构成，强调从过去持续到现在或刚刚停止且影响仍可见的活动。现在完成时更容易突出完成的数量或结果，进行形式则突出过程和时长。状态动词通常不用进行形式。for 引出时长，since 引出起点；句中有一段时间并不自动要求完成进行时，还要判断动作性质与当前是否有关联。本课应用：had been planting 是过去参照点之前一直进行的活动；与 have been planting 的参照点在现在不同。需要明确过去的停顿或报告时刻。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The volunteers had been planting seeds for hours when the rain began.</p></blockquote><p>下雨时，志愿者已经连续播种数小时了。</p><p>had been planting 强调雨开始前持续的活动，when rain began 提供过去参照点。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>had been planted 是被动或状态相关结构，不表示志愿者持续播种；用 planting。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 had been planting 的弱读，重读 for hours，突出持续长度。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The volunteers had been planting seeds for hours when the rain began. They stopped to protect the tools. A month later, small green shoots appeared.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>描述一次持续劳动被天气打断的经历，补充一个较晚的观察结果。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：had been planting 强调雨开始前持续的活动，when rain began 提供过去参照点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：had been planted 是被动或状态相关结构，不表示志愿者持续播种；用 planting。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 plant：They had been ___ seeds for hours.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> planting</p><p><strong>解析：</strong> 过去完成进行时为 had been doing。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>一个月后出现了什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Small green shoots.</p><p><strong>解析：</strong> 示范只描述幼芽，未宣称森林恢复完成。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>过去完成进行时的基本结构是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> had been + 动词-ing</p><p><strong>解析：</strong> 它以过去时点为参照，回顾之前持续的活动。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：完成进行时与持续活动。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-061">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-063">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
